  [ "$NODE_RESTORE_NOGLOB" = 0 ] || set -f
fi
recheck_selected_before_use
pick_port() {
  if [ "$T3_ARCHIVE_MODE" = "1" ]; then
    "$RUNNER_FILE" __ssh-helper pick-port "$PORT_FILE" "3773" "200"
    return
  fi
  node - "$PORT_FILE" "3773" "200" <<'NODE'
const fs = require("node:fs");
const net = require("node:net");
const filePath = process.argv[2] ?? "";
const defaultPort = Number.parseInt(process.argv[3] ?? "", 10);
const scanWindow = Number.parseInt(process.argv[4] ?? "", 10);
const raw = fs.existsSync(filePath) ? fs.readFileSync(filePath, "utf8").trim() : "";
const preferred = Number.parseInt(raw, 10);
const start = Number.isInteger(preferred) ? preferred : defaultPort;
const end = start + scanWindow;

function tryPort(port) {
  return new Promise((resolve) => {
    const server = net.createServer();
    server.unref();
    server.once("error", () => resolve(false));
    server.listen(port, "127.0.0.1", () => {
      server.close((error) => resolve(error ? false : port));
    });
  });
}

(async () => {
  for (let port = start; port < end; port += 1) {
    const available = await tryPort(port);
    if (available) {
      process.stdout.write(String(port));
      return;
    }
  }
  process.exit(1);
})().catch(() => process.exit(1));
NODE
}
wait_ready() {
  if [ "$T3_ARCHIVE_MODE" = "1" ]; then
    "$RUNNER_FILE" __ssh-helper wait-ready "$REMOTE_PORT" "$1" "1000"
    return
  fi
  node - "$REMOTE_PORT" "$1" "1000" <<'NODE'
const http = require("node:http");
const port = Number.parseInt(process.argv[2] ?? "", 10);
const timeoutMs = Number.parseInt(process.argv[3] ?? "", 10);
const probeTimeoutMs = Number.parseInt(process.argv[4] ?? "", 10);
if (!Number.isInteger(port) || !Number.isInteger(timeoutMs) || !Number.isInteger(probeTimeoutMs)) {
  process.exit(1);
}
const deadline = Date.now() + timeoutMs;

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function probe() {
  return new Promise((resolve) => {
    const request = http.get(
      {
        hostname: "127.0.0.1",
        port,
        path: "/",
        timeout: probeTimeoutMs,
      },
      (response) => {
        response.resume();
        response.once("end", () => {
          resolve(response.statusCode >= 200 && response.statusCode < 300);
        });
      },
    );
    request.once("timeout", () => {
      request.destroy();
      resolve(false);
    });
    request.once("error", () => resolve(false));
  });
}

(async () => {
  while (Date.now() < deadline) {
    if (await probe()) {
      process.exit(0);
    }
    await sleep(100);
  }
  process.exit(1);
})().catch(() => process.exit(1));
NODE
}
wait_for_pid_exit() {
  PID_TO_WAIT="$1"
  WAIT_COUNT=0
  while kill -0 "$PID_TO_WAIT" 2>/dev/null && [ "$WAIT_COUNT" -lt 20 ]; do
    WAIT_COUNT=$((WAIT_COUNT + 1))
    sleep 0.1
  done
}
reuse_live_server() {
    REMOTE_PORT="$LIVE_PORT"
    if ! wait_ready "2000"; then
      printf 'Selected live server did not answer; it was left running.\n' >&2; exit 1
    fi
    recheck_selected_before_use
    if [ "$LIVE_COMPATIBLE" != 1 ]; then
      printf 'Live server compatibility changed during readiness; reconnect.\n' >&2; exit 1
    fi
    if [ "$LIVE_OWNED" = 1 ]; then
      REMOTE_PID="$LIVE_PID"
      REMOTE_MANAGED=managed
    else
      REMOTE_MANAGED=external
      rm -f "$PID_FILE" "$STATE_DIR/identity"
      printf '%s\n' "$REMOTE_PORT" >"$PORT_FILE"
      printf 'external\n' >"$MANAGED_FILE"
    fi
}
recheck_selected_before_use
REMOTE_PID=""
REMOTE_PORT=""
REMOTE_MANAGED=""
if [ "$LIVE_STATUS" != none ]; then
  if [ "$LIVE_COMPATIBLE" = 1 ]; then
    reuse_live_server
  elif [ "$NEEDS_OWNED_UPGRADE" = 1 ]; then
    # Recompute retained hash and verify the same live identity immediately before kill.
    recheck_selected_before_use
    if [ "$LIVE_STATUS" != live ] || [ "$LIVE_OWNED" != 1 ] ||
       [ "$NEEDS_OWNED_UPGRADE" != 1 ] || [ "$LIVE_PID" != "$UPGRADE_PID" ] ||
       [ "$LIVE_PORT" != "$UPGRADE_PORT" ] || [ "$LIVE_VERSION" != "$UPGRADE_VERSION" ]; then
      printf 'Owned GOAT identity changed before termination; process was left running.\n' >&2; exit 1
    fi
    if [ "$REFRESH_IF_IDLE" = 1 ]; then
      activity="$(read_refresh_activity)"
      if [ "$activity" != idle ]; then
        case "$activity" in busy) REFRESH_DECISION=reused-busy ;; *) REFRESH_DECISION=reused-unknown ;; esac
        recheck_selected_before_use
        reuse_live_server
      else REFRESH_DECISION=replaced; fi
    fi
    if [ -z "$REMOTE_PORT" ]; then
    if [ "$LEGACY_PENDING" = 1 ] && [ "$LEGACY_COMMITTED" = 0 ]; then
      commit_legacy_identity || ownership_unverified
    fi
    check_retained_runner
    verify_owned_identity "$UPGRADE_PID" "$UPGRADE_PORT" || ownership_unverified
    publish_selected_runner
    cmp -s "$RUNNER_CANDIDATE_FILE.pin" "$RUNNER_FILE" || ownership_unverified
    PID_TO_STOP="$UPGRADE_PID"
    if ! verify_owned_identity "$PID_TO_STOP" "$UPGRADE_PORT"; then
      printf 'GOAT ownership could not be verified for PID %s; process and ownership files were preserved.\n' "$PID_TO_STOP" >&2
      exit 1
    fi
    if [ "$LEGACY_PENDING" = 1 ]; then
      verify_legacy_process "$PID_TO_STOP" "$LEGACY_IDENTITY" || ownership_unverified
      [ "$(read_legacy_value "$PID_FILE")" = "$LEGACY_PID" ] &&
        [ "$(read_legacy_value "$PORT_FILE")" = "$LEGACY_PORT" ] &&
        [ "$(read_legacy_value "$MANAGED_FILE")" = managed ] || ownership_unverified
    fi
    kill "$PID_TO_STOP" 2>/dev/null || true
    wait_for_pid_exit "$PID_TO_STOP"
    if kill -0 "$PID_TO_STOP" 2>/dev/null; then
      printf 'Owned server did not stop; ownership files were preserved.\n' >&2
      exit 1
    fi
    LEGACY_TERMINATED=1
    rm -f "$PID_FILE" "$PORT_FILE" "$MANAGED_FILE" "$STATE_DIR/identity"
    fi
  else
    printf 'Live GOAT compatibility changed; reconnect.\n' >&2; exit 1
  fi
fi
if [ -z "$REMOTE_PORT" ]; then
  REMOTE_PORT="$(pick_port)" || true
  if [ -z "$REMOTE_PORT" ]; then
    if [ "$T3_ARCHIVE_MODE" = "1" ]; then
      printf 'Failed to find an available port on the remote host.\n' >&2
    else
      printf 'Failed to find an available port on the remote host. Ensure node is available on PATH.\n' >&2
    fi
    exit 1
  fi
  recheck_selected_before_use
  if [ "$LIVE_STATUS" != none ]; then
    printf 'A server appeared before launch; reconnect without replacing it.\n' >&2; exit 1
  fi
  if [ "$T3_ARCHIVE_MODE" = 1 ]; then
    T3_RUNTIME_DIR="$HOME/.goat/runtime/goat/versions/$SELECTED_VERSION"
    SPAWN_IDENTITY="$T3_RUNTIME_DIR/goat"
  else
    SPAWN_IDENTITY="$T3_NODE_SCRIPT_PATH"
  fi
  nohup env T3CODE_NO_BROWSER=1 "$RUNNER_FILE" serve --host 127.0.0.1 --port "$REMOTE_PORT" --base-dir "$DEFAULT_SERVER_HOME" >>"$LOG_FILE" 2>&1 < /dev/null &
  REMOTE_PID="$!"
  printf '%s\n' "$SPAWN_IDENTITY serve --host 127.0.0.1 --port $REMOTE_PORT --base-dir $DEFAULT_SERVER_HOME" >"$IDENTITY_NEXT"
  mv "$IDENTITY_NEXT" "$STATE_DIR/identity"
  printf '%s\n' "$REMOTE_PID" >"$PID_FILE"
  printf '%s\n' "$REMOTE_PORT" >"$PORT_FILE"
  printf 'managed\n' >"$MANAGED_FILE"
  if ! wait_ready "60000"; then
    printf 'Remote T3 server did not become ready on 127.0.0.1:%s.\n' "$REMOTE_PORT" >&2
    if [ -s "$LOG_FILE" ]; then
      tail -n 80 "$LOG_FILE" >&2 2>/dev/null || true
    else
      printf 'It wrote nothing to %s, so it exited before producing any output.\n' "$LOG_FILE" >&2
    fi
    kill "$REMOTE_PID" 2>/dev/null || true
    wait_for_pid_exit "$REMOTE_PID"
    rm -f "$PID_FILE" "$PORT_FILE" "$MANAGED_FILE" "$STATE_DIR/identity"
    exit 1
  fi
fi
refresh_fields=
# Double quotes are literal inside single quotes; dash preserves unsupported printf escapes.
case "$REFRESH_DECISION" in
  replaced|reused-busy|reused-unknown) refresh_fields="$(printf ',"refresh":"%s"' "$REFRESH_DECISION")" ;;
esac
if [ "$REFRESH_DECISION" = reused-busy ] || [ "$REFRESH_DECISION" = reused-unknown ]; then
  refresh_fields="$refresh_fields$(printf ',"selectedVersion":"%s"' "$LIVE_VERSION")"
fi
printf '{"remotePort":%s,"serverKind":"%s"%s}\n' "$REMOTE_PORT" "${REMOTE_MANAGED:-managed}" "$refresh_fields"

